default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKCU:\Software\Policies\Microsoft\Assistance\Client\1.0' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('NoImplicitFeedback', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]1)) {
    Write-Output 'Mismatch: HKCU:\Software\Policies\Microsoft\Assistance\Client\1.0 [NoImplicitFeedback]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKCU:\Software\Policies\Microsoft\Assistance\Client\1.0')) {
    New-Item -Path 'HKCU:\Software\Policies\Microsoft\Assistance\Client\1.0' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKCU:\Software\Policies\Microsoft\Assistance\Client\1.0' -Name 'NoImplicitFeedback' -Value 1 -PropertyType DWord -Force | Out-Null
exit 0
